create or replace view public.vehicle_artwork_exact_locked with (security_invoker = true) as select v.operator,v.vehicle_type,v.formation_id,v.livery,v.theme,v.valid_from,v.valid_to,v.image_path from public.vehicle_visual_identities v join public.vehicle_image_review_baselines b on b.image_path=v.image_path join public.vehicle_image_assets a on a.id=b.asset_id where v.identity_status='exact' and v.image_path is not null and b.metadata_lock_eligible=true and a.asset_status='available' and a.appearance_class is distinct from 'temporary_wrapping'
